// sound.rs - pitched tones and tunes for a buzzer on PB3 (board pin 32), generated by a BIO core.
//
// Wiring: buzzer + to board pin 32 (PB3 = BIO3, also PWM1[3]); buzzer - to GND. (A passive buzzer needs the
// tone; an active one will simply sound whenever it is toggled.)
//
// How it works: one of the four BIO cores runs a tiny program that toggles the pin with exact timing, so the
// main CPU does nothing while a note plays. The core's "quantum" clock is set to 100 kHz (10 us per tick); the
// host sends two words per note: half-period in ticks and number of full periods. When it runs out of work the
// core waits on its FIFO with the pin low = silence. (The old CPU-toggled versions flooded the system and were
// removed.)
//
// `Sound::play` never blocks. A background thread plays queued effects first, then the looping background tune
// (if any), one short note at a time so an effect never waits long.
use std::collections::VecDeque;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{channel, Receiver, Sender, TryRecvError};
use std::sync::{Arc, Mutex};

use arbitrary_int::{Number, u5};
use bao1x_api::bio::*;
use bao1x_api::bio_code;
use bao1x_api::bio_resources::*;
use bao1x_hal::bio::{Bio, CoreCsr};
use utralib::utra::bio_bdma;

/// BIO pin number of the buzzer (BIO3 = PB3 = header pin 32).
const BIO_PIN: u8 = 3;
/// Tick rate of the tone core (Hz).
const TICK_HZ: u32 = 100_000;

pub const REST: u32 = 0;
/// (frequency in Hz or REST, duration in ms)
pub type Note = (u32, u32);

// Notes around C#4 (277 Hz), low and gentle on a small buzzer.
pub const CS4: u32 = 277;
pub const DS4: u32 = 311;
pub const E4: u32 = 330;
pub const FS4: u32 = 370;
pub const GS4: u32 = 415;
pub const AS4: u32 = 466;
pub const B4: u32 = 494;
pub const CS5: u32 = 554;
pub const DS5: u32 = 622;
pub const E5: u32 = 659;
pub const GS5: u32 = 831;
pub const B5: u32 = 988;

pub const CLICK: &[Note] = &[(1200, 12)];
pub const COIN: &[Note] = &[(E5, 60), (B5, 120)];
pub const CRASH: &[Note] = &[(E4, 110), (DS4, 110), (CS4, 110), (196, 250)];
pub const TICK: &[Note] = &[(GS4, 30)];
pub const HELLO: &[Note] = &[(CS4, 110), (E4, 110), (GS4, 110), (CS5, 220)];
pub const SCALE: &[Note] = &[
    (CS4, 180), (DS4, 180), (E4, 180), (FS4, 180), (GS4, 180), (AS4, 180), (B4, 180), (CS5, 360),
];
pub const SOS: &[Note] = &[
    (GS4, 90), (REST, 90), (GS4, 90), (REST, 90), (GS4, 90), (REST, 250), (GS4, 270), (REST, 90), (GS4, 270),
    (REST, 90), (GS4, 270), (REST, 250), (GS4, 90), (REST, 90), (GS4, 90), (REST, 90), (GS4, 90),
];
/// Each game's looping background tune (notes <= 200 ms so effects can cut in quickly).
pub const TUNE_DODGER: &[Note] = &[
    (CS4, 160), (E4, 160), (GS4, 160), (E4, 160), (CS4, 160), (E4, 160), (GS4, 160), (CS5, 160),
    (B4, 160), (GS4, 160), (E4, 160), (GS4, 160), (B4, 160), (GS4, 160), (E4, 160), (REST, 160),
];
pub const TUNE_SNAKE: &[Note] = &[
    (E4, 200), (REST, 100), (E4, 100), (FS4, 200), (GS4, 200), (REST, 100), (GS4, 100), (FS4, 200),
    (E4, 200), (DS4, 200), (CS4, 200), (REST, 200),
];
pub const TUNE_PONG: &[Note] = &[(CS4, 120), (REST, 120), (GS4, 120), (REST, 120)];
pub const TUNE_FLAPPY: &[Note] = &[
    (GS4, 150), (B4, 150), (CS5, 150), (B4, 150), (GS4, 150), (E4, 150), (GS4, 300), (REST, 150),
];
pub const TUNE_MENU: &[Note] = &[
    (CS4, 200), (REST, 200), (E4, 200), (REST, 200), (GS4, 200), (REST, 200), (E4, 200), (REST, 600),
];

enum Msg {
    Effect(Vec<Note>),
    Tune(Option<&'static [Note]>),
}

#[derive(Clone)]
pub struct Sound {
    tx: Sender<Msg>,
    pub enabled: Arc<AtomicBool>,
    pub status: Arc<Mutex<String>>,
}

impl Sound {
    pub fn start() -> Sound {
        let (tx, rx) = channel();
        let enabled = Arc::new(AtomicBool::new(true));
        let status = Arc::new(Mutex::new(String::from("starting")));
        let st = status.clone();
        let en = enabled.clone();
        std::thread::Builder::new().name("sound".into()).spawn(move || run(rx, en, st)).ok();
        Sound { tx, enabled, status }
    }

    /// Queue a sound effect (plays before the background tune continues).
    pub fn play(&self, notes: &[Note]) {
        if self.enabled.load(Ordering::Relaxed) {
            self.tx.send(Msg::Effect(notes.to_vec())).ok();
        }
    }

    /// Set (or clear) the looping background tune.
    pub fn tune(&self, t: Option<&'static [Note]>) { self.tx.send(Msg::Tune(t)).ok(); }

    /// Stop the background tune (effects already queued still play).
    pub fn silence(&self) { self.tune(None); }

    pub fn toggle(&self) -> bool {
        let on = !self.enabled.load(Ordering::Relaxed);
        self.enabled.store(on, Ordering::Relaxed);
        if !on {
            self.tune(None);
        }
        on
    }

    pub fn status_text(&self) -> String { self.status.lock().map(|s| s.clone()).unwrap_or_default() }
}

// FIFO1 (x17) input: first word = pin mask, then pairs (half-period ticks, full periods) per note.
// The pin idles low while the core waits on the FIFO.
#[rustfmt::skip]
bio_code!(tone_kernel, TONE_START, TONE_END,
    "mv x4, x17",   // pin mask
    "mv x26, x4",   // apply the mask to all GPIO operations
    "mv x24, x4",   // make the pin an output
    "mv x23, x0",   // drive it low
"10:",
    "mv x8, x17",   // half period in ticks (blocks until the host sends it)
    "mv x9, x17",   // number of full periods
"20:",
    "mv x22, x4",   // pin high
    "mv x10, x8",
"21:",
    "mv x20, x0",   // wait one tick
    "addi x10, x10, -1",
    "bne x10, x0, 21b",
    "mv x23, x0",   // pin low
    "mv x10, x8",
"22:",
    "mv x20, x0",
    "addi x10, x10, -1",
    "bne x10, x0, 22b",
    "addi x9, x9, -1",
    "bne x9, x0, 20b",
    "j 10b"
);

struct Tone {
    _bio: Bio,
    _handle: CoreHandle,
    tx: CoreCsr,
}

fn init_tone() -> Result<Tone, String> {
    let mut bio = Bio::new();
    let spec = ResourceSpec {
        claimer: "ChocoTone".to_string(),
        cores: vec![CoreRequirement::Any],
        fifos: vec![Fifo::Fifo1],
        static_pins: vec![],
        dynamic_pin_count: 1,
    };
    let grant = bio.claim_resources(&spec).map_err(|e| format!("claim {:?}", e))?;
    let config = CoreConfig { clock_mode: ClockMode::TargetFreqInt(TICK_HZ) };
    bio.init_core(grant.cores[0], tone_kernel(), config).map_err(|e| format!("init {:?}", e))?;
    bio.set_core_run_state(&grant, true);
    bio.claim_dynamic_pin(BIO_PIN, &spec.claimer).map_err(|e| format!("pin {:?}", e))?;
    let mut io = IoConfig::default();
    io.mapped = 1 << u5::new(BIO_PIN).as_u32();
    io.mode = IoConfigMode::Overwrite;
    bio.setup_io_config(io).map_err(|e| format!("io {:?}", e))?;
    // safety: the handle is stored in the Tone object so it outlives the CSR view
    let handle = unsafe { bio.get_core_handle(Fifo::Fifo1) }
        .map_err(|e| format!("fifo {:?}", e))?
        .ok_or_else(|| "no FIFO1 handle".to_string())?;
    let mut tx = CoreCsr::from_handle(&handle);
    tx.csr.wo(bio_bdma::SFR_TXF1, io.mapped);
    Ok(Tone { _bio: bio, _handle: handle, tx })
}

impl Tone {
    /// Start a note and return immediately (the core plays it by itself).
    fn start(&mut self, hz: u32, ms: u32) {
        let half = (TICK_HZ / (2 * hz.clamp(50, 5000))).max(1);
        let periods = (hz as u64 * ms as u64 / 1000).max(1) as u32;
        self.tx.csr.wo(bio_bdma::SFR_TXF1, half);
        self.tx.csr.wo(bio_bdma::SFR_TXF1, periods);
    }
}

fn run(rx: Receiver<Msg>, enabled: Arc<AtomicBool>, status: Arc<Mutex<String>>) {
    let tt = ticktimer::Ticktimer::new().unwrap();
    tt.sleep_ms(3500).ok(); // after the rest of the system has started
    let mut tone = match init_tone() {
        Ok(t) => {
            if let Ok(mut s) = status.lock() {
                *s = "BIO tone ok".into();
            }
            Some(t)
        }
        Err(e) => {
            log::error!("sound: BIO tone init failed: {}", e);
            if let Ok(mut s) = status.lock() {
                *s = format!("BIO fail: {}", e);
            }
            None
        }
    };
    let mut effects: VecDeque<Note> = VecDeque::new();
    let mut tune: Option<&'static [Note]> = None;
    let mut idx = 0usize;
    loop {
        // collect messages without blocking; block only when there is nothing to play
        loop {
            let m = if effects.is_empty() && tune.is_none() {
                match rx.recv() {
                    Ok(m) => m,
                    Err(_) => return,
                }
            } else {
                match rx.try_recv() {
                    Ok(m) => m,
                    Err(TryRecvError::Empty) => break,
                    Err(TryRecvError::Disconnected) => return,
                }
            };
            match m {
                Msg::Effect(v) => effects.extend(v),
                Msg::Tune(t) => {
                    tune = t;
                    idx = 0;
                }
            }
        }
        let on = enabled.load(Ordering::Relaxed);
        let note = if let Some(n) = effects.pop_front() {
            Some(n)
        } else if let (Some(t), true) = (tune, on) {
            let n = t[idx % t.len()];
            idx += 1;
            Some(n)
        } else {
            None
        };
        if let Some((hz, ms)) = note {
            if hz != REST && on {
                if let Some(t) = tone.as_mut() {
                    t.start(hz, ms);
                }
            }
            tt.sleep_ms(ms as usize + 10).ok(); // 10 ms gap so repeated notes are distinct
        } else if tune.is_some() && !on {
            tt.sleep_ms(100).ok();
        }
    }
}
